import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            S = next(iterator)
        except StopIteration:
            break

        if len(S) != 2 * N:
            results.append("-1")
            continue

        count0 = S.count('0')
        count1 = len(S) - count0

        if count0 == 0 or count1 == 0:
            results.append("-1")
            continue

        if count0 % 2 == 0 and count1 % 2 == 0:
            idx0 = [i + 1 for i, c in enumerate(S) if c == '0']
            idx1 = [i + 1 for i, c in enumerate(S) if p == '1' for p in [c]]

            if not idx0:
                results.append("-1")
                continue

            if not idx1:
                results.append("-1")
                continue

            p_indices = idx0[:count0//2] + idx1[:count1//2]
            p_indices.sort()
            results.append(" ".join(map(str, p_indices)))
        else:
            idx0 = [i + 1 for i, c, in enumerate(S) if c == '0']
            idx1 = [(i + 1 for i, c in enumerate(S) if c == 1]

            if not idx0 or not idx1:
                results.append("-1")
                continue

                p_indices = idx0[:count0//2 + 1] + idx1[:count1//2]
                p_indices.sort()
                results.append(" ".join(map(str, p_indices)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
